@asm_pio(                                       # Bank selection via A15..A18
    out_init=(PIO.OUT_LOW, ) * 4, 
    out_shiftdir=PIO.SHIFT_RIGHT,
    autopull=True,
    pull_thresh=8,
    )
def sel_bank():
    wrap_target()
    pull(noblock)
    mov(x, osr)
    wait (0, gpio, 13)
    jmp(pin, "low")
    out(null, 4)
    out(pins, 4)
    jmp("fin")
    label("low")
    out(pins, 4)
    label("fin")
    wait (1, gpio, 13)
    wrap()
    

@asm_pio(                                       # Control lines: /BE, A14_L, /U10_CE /U10_OE
    set_init=(PIO.OUT_HIGH, ) * 2,
    in_shiftdir=PIO.SHIFT_LEFT,
    out_init=(PIO.OUT_HIGH, ) * 2,
    out_shiftdir=PIO.SHIFT_RIGHT,
    autopull=True,
    pull_thresh=8,
    )
def set_ctrl():
    wrap_target()
    mov(pins, invert(null))
    mov(y, null)
    set(pins, 3)
    pull(noblock)
    mov(x, osr)
    wait (0, gpio, 13)
    nop()                  [2]
    jmp (pin, "low")
    out(null, 2)
    out(pins, 2)
    jmp("pass")
    label("low")
    in_(pins, 2)
    mov(y, isr)
    mov(isr, null)
    jmp(y_dec, "home")
    set(pins, 2)
    jmp("wait")
    label("home")
    jmp(y_dec, "pass")
    set(pins, 0)
    label("wait")
    nop()                  [10]
    out(pins, 2)
    label("pass")
    wait (1, gpio, 13)
    wrap()


@asm_pio(                                       # Control lines /U10_CE /U10_OE only; for DCK access with not ROM mapping
    out_init=(PIO.OUT_HIGH, ) * 2,
    out_shiftdir=PIO.SHIFT_RIGHT,
    autopull=True,
    pull_thresh=8,
    )
def set_dck():
    wrap_target()
    mov(pins, invert(null))
    pull(noblock)
    mov(x, osr)
    wait (0, gpio, 13)
    nop()                  [2]
    jmp (pin, "pass")
    out(null, 2)
    out(pins, 2)
    jmp("pass")
    label("pass")
    wait (1, gpio, 13)
    wrap()


@asm_pio(                                # This routine adapted from https://github.com/keyvin/docnotes/blob/master/z80/Python/z80io.py
    sideset_init=(PIO.OUT_HIGH),
    out_init=(PIO.OUT_LOW,) * 8, 
    out_shiftdir=PIO.SHIFT_RIGHT,
    in_shiftdir=PIO.SHIFT_LEFT,
    )
def TS_IO():
    wait (0, gpio, 14)      .side(1)     # We first wait for GPIO14=/PICOSEL to be low, then
    jmp(pin, "rd")          .side(1)     # ...if GPIO11=1 then it's a READ
    pull(noblock)           .side(0)
    out(pins, 8)            .side(0)     # if not, simply send all 8 bits
    jmp("fin")              .side(0)     # and JUMP to the end of the PIO program
    label("rd")                          # If it's a WRite, ...
    nop()                   .side(0)
    in_(pins, 9)            .side(0) [2] # we sample D0..D7 and A0. Notice the extra 2 cycles for sync
    push(noblock)           .side(0)
    label("fin")
    wait (1, gpio, 14)      .side(0)
    mov(null, osr)          .side(1)


@asm_pio(
    sideset_init=(PIO.OUT_HIGH),
    out_init=(PIO.OUT_LOW,) * 8,
    out_shiftdir=PIO.SHIFT_RIGHT,
    in_shiftdir=PIO.SHIFT_LEFT,
)
def TS_IO_DUAL():
    """Dual-port PIO: handles both port $0E (data) and port $0F (status).

    Pin assignments (unchanged from TS_IO):
      GPIO 2-9   = D0-D7 (out_base / in_base)
      GPIO 10    = A0 (bit 8 of in_(pins, 9) — distinguishes ports)
      GPIO 11    = R/W select (jmp_pin)
      GPIO 12    = U6 buffer enable (sideset)
      GPIO 14    = /PICOSEL (wait gpio)

    Port mapping:
      A0 = 0  →  port $0E (data)
        Z80 IN  : output from TX FIFO via pull(noblock)
        Z80 OUT : sample data + push 9 bits to RX FIFO
      A0 = 1  →  port $0F (status)
        Z80 IN  : output scratch register Y (bit 6 = ready flag)
        Z80 OUT : same 9-bit push (Python checks bit 8 to identify port)

    Python controls the ready flag via:
      MQ.exec("mov(y, ~null)")   # Y = 0xFFFFFFFF (bit 6 set) → "ready"
      MQ.exec("set(y, 0)")        # Y = 0 → "not ready"

    Run at freq=30_000_000 (was 15_000_000 for TS_IO). The dual-port
    decode adds ~7 cycles to the read path; 30MHz keeps total under
    the Z80's data setup window. RP2040 PIO can handle up to half the
    system clock (135MHz at 270MHz CPU), so 30MHz is conservative.

    Total 19 instructions of 32 available.
    """
    # ---- Wait for bus cycle ----
    wait(0, gpio, 14)       .side(1)      # /PICOSEL low = bus cycle starts
    jmp(pin, "z80_out")     .side(1)      # GPIO 11: 1=Z80 OUT, 0=Z80 IN

    # ---- Z80 IN (Pico → bus): decode A0 to choose port ----
    in_(pins, 9)            .side(0)      # capture D0-D7 + A0 (bit 8)
    mov(osr, isr)           .side(0)      # ISR → OSR for shifting
    mov(isr, null)          .side(0)      # clear ISR for reuse
    out(null, 8)            .side(0)      # discard D0-D7 (low 8 bits)
    out(x, 1)               .side(0)      # X = remaining bit 0 = A0
    jmp(not_x, "rd_data")   .side(0)      # A0=0 → port $0E (data)

    # Port $0F read: output status from scratch Y
    mov(osr, y)             .side(0)      # Y = status byte
    out(pins, 8)            .side(0)      # drive status onto bus
    jmp("fin")              .side(0)

    # Port $0E read: output data from TX FIFO
    label("rd_data")
    pull(noblock)           .side(0)      # next byte (or stale OSR if empty)
    out(pins, 8)            .side(0)      # drive data onto bus
    jmp("fin")              .side(0)

    # ---- Z80 OUT (bus → Pico): capture data + A0 ----
    label("z80_out")
    nop()                   .side(0)
    in_(pins, 9)            .side(0) [2]  # sample D0-D7 + A0 (extra cycles for setup)
    push(noblock)           .side(0)      # bit 8 of pushed value = A0

    # ---- Cycle complete ----
    label("fin")
    wait(1, gpio, 14)       .side(0)      # wait /PICOSEL deasserted
    mov(null, osr)          .side(1)      # clear OSR, return to idle


def ABORT_TX(log_level):
    
    global dead
    global busy
    
    LOG_ADD("ERROR: LOAD_TS failed!", 2, log_level)
    dead = True
    
    while busy:
        pass
    
    return


def BLINK():                                                                                        # An onboard LED-blinking routine. This for an error condition. Interval is fixed

    led = Pin(25, Pin.OUT)
    led.value(1)

    for i in range(10):
        utime.sleep(.1)
        led.toggle()
    
    led.value(0)
        
    return


def ENA_MQ(MQ):                                                                                # Re-enable TX/RX SM, after a SDCard access

    MQ = StateMachine(0, TS_IO, freq=15_000_000, out_base=Pin(2, Pin.OUT),
                      in_base=Pin(2, Pin.IN), jmp_pin=Pin(11),
                      sideset_base=Pin(12, Pin.OUT))
    
    MQ.active(1)
    
    return MQ
    

def ENA_SD():                                                                              # Enable SD-Card access SM, after TX/RX operation
    
    U3_CS       = Pin(28, Pin.OUT, Pin.PULL_UP)
    D0          = Pin(2,  Pin.IN)
    D1          = Pin(3,  Pin.IN)
    D2          = Pin(4,  Pin.IN)

    spi = SPI(0, sck=D0, mosi=D1, miso=D2)
    sd = SDCard(spi, U3_CS)

    try:
        os.mount(sd, "/sd")
    except:
        LOG_ADD("ERROR: Mounting SD Card failed in ENA_SD!", 2, TSP.LOG_LEVEL)
        spi = -99
        pass
    
    return spi


def END_MSG(MQ, verbose, msg, msg1, st: bytes):                                                             # Sends one-line status message(s)
                                                                                                # back to the TS, once a command is finished
    # Dual-port: continue flag (was wrt(0x40)) is on port $0F via scratch
    # Y, not in the data stream. Y was set to 0xFFFFFFFF by main loop's
    # MQ_READY() before dispatching, and stays ready throughout the LVM
    # transfer. We just stream the status bytes through port $0E's FIFO.
    # For verbose: 0x81 IS the status byte (PRINT_STRING directive).
    # For non-verbose: just the status code.
    wrt = MQ.put

    if verbose:

        wrt(0x81)               # PRINT_STRING directive — IS the byte-N status
        wrt(st)
        wrt(0x0D)
        for m in msg:
            wrt(m)
        if msg1:
            wrt(0x0D)
            for m in msg1:
                wrt(m)
        wrt(0x00)

    else:

        wrt(st)                 # status (0x01 = OK)

    while(MQ.tx_fifo() !=0):
        pass

    return


def LOG_ADD(msg, level, log_level):                                                                    # Adds a timestamped new entry to log_entries
    
    global log_entries
    
    if level < log_level:
        return
    
    log_entries += "[" + str(time.ticks_us()) + "] "                                    # on Pico W, timestamp can be replaced by local time provided by ntp
    log_entries += msg + "\n"
    
    return


def LOAD_TS(pre, MQ, TSP):                                                                                    # Performs LOAD command on the TS side

    global dead
    global kill
    global busy

    global log_entries
    log_entries = ""

    print("[LOADTS] enter pre=%s f_name=%s totlen=%d offset=%d tap_idx=%d tx=%d rx=%d" % (
        list(pre), TSP.f_name, TSP.totlen, TSP.offset, TSP.tap_idx,
        MQ.tx_fifo(), MQ.rx_fifo()))

    Ryan = True

    led = Pin(25, Pin.OUT)
    led.value(1)

    totbytes = 0
    blq_t = 0
    crc = 0
    length = 0

    hdr = bytearray()
    msg = ""

    blk_info = bytearray(3)
    el = bytearray(1)

    if (not TSP.f_name or TSP.totlen == 0):
        local_fname = "/assets/nofile.tap"
        LOG_ADD("WARNING: no file mounted in LOAD_TS", 1, TSP.LOG_LEVEL)
    else:
        local_fname = "/TMP/temp.tap"

    print("[LOADTS] opening %s" % local_fname)
    arch = open(local_fname, "rb")
    arch.seek(TSP.offset)

    arch.readinto(blk_info)

    totbytes = blk_info[0] + 256 * blk_info[1]
    print("[LOADTS] blk_info: len=%d type=0x%02X (totbytes=%d)" % (
        blk_info[0] + 256*blk_info[1], blk_info[2], totbytes))
    
    if (pre[0] != blk_info[2]):
        LOG_ADD("WARNING: Wrong block type in LOAD_TS. Moving ahead 1 block.", 1, TSP.LOG_LEVEL)
        
        TSP.offset += totbytes + 2
        TSP.tap_idx += 1
        
        if (TSP.offset >= TSP.totlen):
            TSP.tap_idx = 0
            TSP.offset = 0
            LOG_ADD("WARNING: EOF reached while searching in LOAD_TS; filename doesn't exist; rewinding.", 1, TSP.LOG_LEVEL)
            
        arch.seek(TSP.offset)
        arch.readinto(blk_info)
        
        totbytes = blk_info[0] + 256 * blk_info[1]
        
        BLINK()
        
    length = pre[7] + 256*pre[8] + 2
    
    if (length != totbytes):
        LOG_ADD("WARNING: Mismatch block length in LOAD_TS; ignoring", 1, TSP.LOG_LEVEL)
        
    dead = False

    r = range(totbytes - 1)

    _thread.start_new_thread(WATCHDOG, (3, MQ, TSP))

    if (blk_info[2] == 0x00):                                                                                           # This is to overcome autorun error when LOADing a non-autorun program
        hdr = bytearray(totbytes - 1)
        arch.readinto(hdr)

        if (Ryan) and (hdr[0] == 0x00) and (hdr[14] >= 0x80):

            hdr[14] = 0x28
            hdr[17] = hdr[17] ^ 0x80 ^ hdr[14]

    wrt = MQ.put

    print("[LOADTS] starting wrt loop. tx=%d rx=%d. block_type=0x%02X" % (
        MQ.tx_fifo(), MQ.rx_fifo(), blk_info[2]))

    # Dual-port: 0x40 continue flag is on port $0F (Y register).
    wrt(blk_info[2])

    # Track Z80 incoming bytes during the wrt loop — capture whatever
    # the Z80 sends back during the data transfer.
    z80_sent = []

    bytes_sent = 0
    if (blk_info[2] == 0x00):
        for el in hdr:
            wrt(el)
            bytes_sent += 1
            # Capture any bytes Z80 sent
            while MQ.rx_fifo() > 0 and len(z80_sent) < 8:
                z80_sent.append(MQ.get())
            if kill:
                print("[LOADTS] KILLED in hdr loop after %d bytes. tx=%d rx=%d z80_sent=%s" % (
                    bytes_sent, MQ.tx_fifo(), MQ.rx_fifo(),
                    [hex(b) for b in z80_sent]))
                ABORT_TX(TSP.LOG_LEVEL)
                return MQ, TSP, log_entries
    else:

        for i in r:
            arch.readinto(el)
            wrt(el)
            bytes_sent += 1
            while MQ.rx_fifo() > 0 and len(z80_sent) < 8:
                z80_sent.append(MQ.get())

            if kill:
                print("[LOADTS] KILLED in data loop after %d bytes. tx=%d rx=%d z80_sent=%s" % (
                    bytes_sent, MQ.tx_fifo(), MQ.rx_fifo(),
                    [hex(b) for b in z80_sent]))
                ABORT_TX(TSP.LOG_LEVEL)
                arch.close()
                return MQ, TSP, log_entries

    print("[LOADTS] wrt loop complete, %d bytes sent. tx=%d rx=%d z80_sent=%s" % (
        bytes_sent, MQ.tx_fifo(), MQ.rx_fifo(),
        [hex(b) for b in z80_sent]))

    arch.close()

    print("[LOADTS] waiting for blq_t echo from Z80...")
    blq_t = MQ.get()
    print("[LOADTS] got blq_t=0x%02X. waiting for crc..." % blq_t)
    crc = MQ.get()
    print("[LOADTS] got crc=0x%02X" % crc)
 
    TSP.tap_idx += 1
    TSP.offset += totbytes + 2
    
    if (TSP.f_name):
        if (TSP.f_name[-4:].upper() == ".TAP"):
            if ((TSP.totlen != 0) and (TSP.offset >= TSP.totlen)):
                TSP.tap_idx = 0
                TSP.offset = 0
                LOG_ADD("WARNING: reached end of offset table, rewinding...", 1, TSP.LOG_LEVEL)
    else:
        if TSP.offset >= os.stat("/assets/nofile.tap")[6]:
            TSP.tap_idx = 0
            TSP.offset = 0
            
    msg = str(totbytes) + " bytes loaded OK"
        
    END_MSG(MQ, TSP.VERBOSE, msg, "", 1)

    dead = True
    
    return MQ, TSP, log_entries


def LOAD_ZX(MQ, TSP):                                                                                          # Performs LOAD command on the TS side; ZX Spectrum-compatible mode
    
    global dead
    global kill
    global busy
    
    global log_entries
    log_entries = ""
    
    led = Pin(25, Pin.OUT)
    led.value(1)
   
    totbytes = 0
    
    blk_info = bytearray(3)
    el = bytearray(1)

    if (not TSP.f_name or TSP.totlen == 0):
        local_fname = "/assets/nofile.tap"
        LOG_ADD("WARNING: no file mounted in LOAD_ZX", 1, TSP.LOG_LEVEL)
    else:    
        local_fname = "/TMP/temp.tap"

    arch = open(local_fname, "rb")
    arch.seek(TSP.offset)

    arch.readinto(blk_info)
    totbytes = blk_info[0] + 256 * blk_info[1]
    
    dead = False
    r = range(totbytes)
    
    _thread.start_new_thread(WATCHDOG, (3, MQ, TSP))

    wrt = MQ.put
    # Dual-port: 0x40 continue flag is on port $0F (scratch Y).
    wrt(blk_info[2])
    
    for i in r:
        arch.readinto(el)
        wrt(el)
        
        if kill:
            ABORT_TX(TSP.LOG_LEVEL)
            arch.close()
            
            return MQ, TSP, log_entries
       
    arch.close()
    
    TSP.offset += totbytes + 2
    TSP.tap_idx += 1
    
    if (TSP.offset >= TSP.totlen):
        TSP.offset = 0
        TSP.tap_idx  = 0
        
        LOG_ADD("WARNING: reached end of offset table in LOAD_ZX, rewinding...", 1, TSP.LOG_LEVEL)
    
    dead = True
   
    return MQ, TSP, log_entries


def LOAD_ZX_C(MQ, TSP, buf_size):                                                                  # ZX Spectrum LOAD routine in compatibility mode
                                                                                                   # *VERY* non-optimized routine, bad memory management. Can hang the Pico, but gets some .TAPs working
    global log_entries
    log_entries = " "
    
    cur_buf = []
    
    if (TSP.offset >= TSP.totlen):
        return MQ, TSP, log_entries
    
    size_rd = TSP.totlen - TSP.offset
    
    if (size_rd >= buf_size):
        size_rd = buf_size
    rd_bytes = bytearray(size_rd)
    
    if (not TSP.f_name or TSP.totlen == 0):
        local_fname = "/assets/nofile.tap"
        LOG_ADD("WARNING: no file mounted in LOAD_ZX_C", 1, TSP.LOG_LEVEL)
    else:    
        local_fname = "/TMP/temp.tap"
        
    arch = open(local_fname, "rb")
    arch.seek(TSP.offset)
    
    try:
        arch.readinto(rd_bytes)
    except:
        LOG_ADD("ERROR: while reading file in LOAD_ZX_C!", 2, TSP.LOG_LEVEL)
        return MQ, TSP, log_entries
        
    arch.close()
    
    TSP.offset += len(rd_bytes)
    
    while (rd_bytes):
        gc.collect()
        long = rd_bytes[0] + (256*rd_bytes[1])
        
        if (long > len(rd_bytes)):
            TSP.offset -= len(rd_bytes)
            break
        hasta = long + 2

        cur_buf.append(rd_bytes[2:hasta])
        gc.collect()

        rd_bytes = rd_bytes[hasta:]
        gc.collect()
        
    del rd_bytes
    gc.collect()
    
    wrt = MQ.put
    led = Pin(25, Pin.OUT)
    
    for ar in cur_buf:

        led.value(1)
        # Dual-port: 0x40 (= 64) continue flag is on port $0F (scratch Y).
        # MQ.put(64) removed — just stream data bytes.

        for el in ar:
            MQ.put(el)

        led.value(0)
        
    while(MQ.tx_fifo() != 0):
        pass
    
    cur_buf = []
    
    return MQ, TSP, log_entries


def SAVE_TS(MQ, TSP):                                                                                              # Performs SAVE command on the TS side
    
    global busy
    global dead
    global kill
    
    global log_entries
    log_entries = ""
    
    dead = False
    log_entries = ""
    
    r1 = range(21)
    crc_h = 0
    ant = 0
    wrt = MQ.put
    
    gc.collect()
    
    hdr = bytearray(21)

    # Dual-port: 0x40 continue flag is on port $0F (scratch Y).
    # No 0x40 in FIFO — just read incoming header bytes.
    for i in r1:
        hdr[i] = MQ.get()
        
    for i in r1:
        if (i == 1) or (i == 2):
            continue
        ant = crc_h
        crc_h = crc_h ^ hdr[i]
        
    if (hdr[i] !=  ant):
        LOG_ADD("ERROR: Bad CRC in SAVE_TS!", 2, TSP.LOG_LEVEL)
        dead = True
        return MQ, TSP, log_entries
        
    long = (256*hdr[15]) + hdr[14] + 4
    r2 = range(long)
    blk = bytearray(long)

    # Dual-port: 0x40 continue flag is on port $0F (scratch Y).
    # Just send the status byte.
    wrt(0x01)
            
    _thread.start_new_thread(WATCHDOG, (5, MQ, TSP))
    
    t_init = time.ticks_us()
    t_out = False
    
    while (MQ.rx_fifo() == 0):
        if (time.ticks_us() - t_init >= 1_000_000):
            
            t_out = True
            break
        
    if t_out:
        
        LOG_ADD("ERROR: SAVE_TS aborted by pressing BREAK!" + str(MQ.tx_fifo()) + " " + str(MQ.rx_fifo()), 2, TSP.LOG_LEVEL)
        blk = []
        dead = True
        
        while busy:
            pass
        
        return MQ, TSP, log_entries
    
    for i in r2:
        blk[i] = MQ.get()
    
        if kill:
            LOG_ADD("ERROR: SAVE_TS failed!" + str(MQ.tx_fifo()) + " " + str(MQ.rx_fifo()), 2, TSP.LOG_LEVEL)
            dead = True
            blk = []
            
            return MQ, TSP, log_entries
    
    totbytes = long + len(hdr)
    
    dead = True
    
    l_hdr = len(hdr) - 2
    hdr1 = int(l_hdr / 256)
    hdr0 = l_hdr - (hdr1 * 256)
    
    l_blk = len(blk) - 2
    blk1 = int (l_blk / 256)
    blk0 = l_blk - (blk1 * 256)
    
    hdr[2] = hdr[0]
    hdr[0] = hdr0
    hdr[1] = hdr1
    
    blk[2] = blk[0]
    blk[0] = blk0
    blk[1] = blk1
    
    if TSP.f_name and TSP.append:
        filename = TSP.f_name
        mode = "ab"
        
    else:
        filename = hdr[4:14].decode()
        filename = filename.strip()        
        # clean_fname = ''.join(l for l in filename if (l.isalpha() or l.isdigit() or l.isspace()))
        clean_fname = ''.join(l for l in filename if (l.isalpha() or l.isdigit() or l=='_' or l=='-'))
        
        if clean_fname != filename:
            msg = 'ERROR: Filename "%s" not allowed' % filename
            END_MSG(MQ, True, msg, [], 3) # STAT_3_F_Invalid_filename
            
            return MQ, TSP, log_entries
            
        if not clean_fname:
            clean_fname = "noname"
        
        filename = clean_fname + ".tap"
        filename = TSP.cur_path + "/" + filename
        mode = "wb"
        
        TSP.f_name = filename

    msg = "80 - " + str(totbytes) + " bytes saved OK"
    END_MSG(MQ, TSP.VERBOSE, msg, [], 1)

    ENA_SD()
    
    with open(filename, mode) as f1:
        f1.write(hdr)
        f1.write(blk)
    
    os.chdir(TSP.cur_path)    
        
#     os.umount("/sd")
#     MQ = ENA_MQ(MQ)
    
    hdr = []
    blk = []
    
    gc.collect()
    
    LOG_ADD("INFO: Finished SAVE TS successfully" +str(MQ.tx_fifo()) + " " + str(MQ.rx_fifo()), 0, TSP.LOG_LEVEL)

    return MQ, TSP, log_entries


def SAVE_ZX(MQ, TSP):                                                                                             # ZX Spectrum-compatible SAVE routine
    
    global kill
    global dead
    global busy
    
    global log_entries
    log_entries = ""
    
    dead = False
    
    r1 = range(21)
    crc_h = 0
    ant = 0
    wrt = MQ.put
    
    hdr = bytearray(21)
    
    _thread.start_new_thread(WATCHDOG, (5, MQ, TSP))
    
    for i in r1:
        hdr[i] = MQ.get()
        
    long = (256*hdr[15]) + hdr[14] + 4
    r2 = range(long)
    
    blk = bytearray(long)
    
    MQ.get()
    
    for i in r2:
        blk[i] = MQ.get()
        if kill:
            LOG_ADD("ERROR: SAVE_ZX failed! " + str(MQ.tx_fifo()) + " " + str(MQ.rx_fifo()), 2, TSP.LOG_LEVEL)
            dead = True
            blk = []
            
            return MQ, TSP, log_entries

    dead = True
    
    while(MQ.rx_fifo() != 0):
        fff = MQ.get()

    hdr[0] = 19
    
    l_blk = len(blk) - 2
    
    blk1 = int (l_blk / 256)
    blk0 = l_blk - (blk1 * 256)
    
    blk[0] = blk0
    blk[1] = blk1
    
    filename = hdr[4:14].decode()
    filename = filename.strip() + ".tap"
    filename = TSP.cur_path + "/" + filename
    
    ENA_SD()
    
    with open(filename, 'wb') as f1:
        f1.write(hdr)
        
    with open(filename, 'ab') as f1:
        f1.write(blk)
        
    hdr = []
    blk = []
    
    while(MQ.tx_fifo() != 0):
        pass
    
    while(MQ.rx_fifo() != 0):
        fff = MQ.get()
        
    os.umount("/sd")
    MQ = ENA_MQ(MQ)

    LOG_ADD("INFO: Finished SAVE ZX successfully " + str(MQ.tx_fifo()) + " " + str(MQ.rx_fifo()), 0, TSP.LOG_LEVEL)

    return MQ, TSP, log_entries


def WATCHDOG(secs, MQ, TSP):                                                                                 # Watchdog that executes on the second thread, 
                                                                                                      
    global kill
    global dead
    global busy
    
    led = Pin(25, Pin.OUT)
    
    kill = False
    busy = True
    
    LOG_ADD("INFO: Starting watchdog...", 0, TSP.LOG_LEVEL)
    secs = secs * 1_000_000
    
    led.value(1)
    
    t_init = time.ticks_us()
    
    while (time.ticks_us() - t_init) < secs:
        if dead:
            break
    if not dead:
        LOG_ADD("ERROR: Abnormal termination. Clearing TX/RX FIFO....", 2, TSP.LOG_LEVEL)
        while not dead:
            MQ.exec("pull (noblock)")
            MQ.exec("mov (osr, null)")
            MQ.exec("mov (isr, null)")
            MQ.exec("push (noblock)")
            kill = True
             
        while MQ.rx_fifo() != 0:
            MQ.get()
        while MQ.tx_fifo() != 0:
            MQ.exec("pull (noblock)")
            MQ.exec("set (osr, null)")
        MQ.active(0)
        
        LOG_ADD("INFO: TX/RX FIFO successfully cleared. Operation finished", 0, TSP.LOG_LEVEL)
        
        BLINK()
        
        MQ.active(1)
        
        LOG_ADD("INFO: Ending watchdog. Operation ended normally", 0, TSP.LOG_LEVEL)
        
    kill = False
    busy = False
    
    led.value(0)